namespace hanmo::resident {namespace {
template<class T>Outcome<T> fail(const StableId& code){return {false,{},common_failure(code).error};}
bool before(const CommonStore& c,const StableId& a,const StableId& b){const auto& o=c.state().facts.order();auto x=std::find(o.begin(),o.end(),a),y=std::find(o.begin(),o.end(),b);return x!=o.end()&&y!=o.end()&&x<y;}
bool head(const CommonStore& c,const StableId& id,const StableId& prefix,const StableId& kind,const StableId& domain){const auto n=organization_instance_sequence(id,prefix);const auto* h=c.state().facts.find(id);return n&&*n<c.state().next_instance_id&&h&&h->id==id&&h->kind==kind&&h->domain==domain;}
Outcome<StableId> fact(CommonStore& c,const StableId& prefix,const StableId& kind,const StableId& domain){auto id=c.next_id(prefix);if(!id.ok)return id;auto valid=c.append_fact({id.value,kind,domain});return valid.ok?id:Outcome<StableId>{false,{},valid.error};}
Outcome<Integer> reserved(const CommonStore& c,const StableId& wallet,const StableId& action){const auto* w=c.wallet(wallet);if(!w)return fail<Integer>("PrivateShopStaffWalletMissing");Integer amount=0;bool seen=false;for(const auto& hold:w->reserved)if(hold.action_id.kind==ReservationRef::Kind::action&&hold.action_id.id==action){if(seen||hold.amount<=0)return fail<Integer>("PrivateShopStaffReservationMismatch");amount=hold.amount;seen=true;}return {true,amount,{}};}
bool exact_operation(const PrivateShopContext&x,const PrivateShopOperation&o){if(!x.exact_operations)return false;for(const auto&a:x.exact_operations->sources.accepted_operations)if(a.operation_ref==o.id)return true;return false;}
bool original_staff_terminal_order(const PrivateShopContext&x,const PrivateShopOperation&o,const PrivateShopStaffContract&contract){
 if(contract.terminal_fact_id.empty())return true;
 if(!before(x.common,o.id,contract.terminal_fact_id)||o.result_fact_id.empty())return false;
 if(before(x.common,o.result_fact_id,contract.terminal_fact_id))return true;
 if(!x.exact_operations||!before(x.common,contract.terminal_fact_id,o.result_fact_id))return false;
 const auto*result=x.state.operating_results.find(o.result_fact_id);if(!result||result->completed||result->reason!="PrivateShopStaffTerminated")return false;
 const PrivateShopOperationTerminalSource*terminal=nullptr;for(const auto&row:x.exact_operations->sources.terminal_sources)if(row.operation_ref==o.id){if(terminal)return false;terminal=&row;}
 if(!terminal||terminal->original_result_ref.id!=o.result_fact_id||terminal->original_result_ref.domain!=private_shop_module||terminal->original_result_ref.kind!="private_shop_operating_interrupted"||terminal->actual_cause_ref.source_schema!=1||!same_source_ref(terminal->actual_cause_ref.source_ref,{private_shop_module,"private_shop_staff_ended",contract.terminal_fact_id}))return false;
 auto original=read_private_shop_exact_staff_terminal(*x.exact_operations,terminal->actual_cause_ref.source_ref);if(!original.ok)return false;auto same=compare_world_moments(original.value.occurred_at,terminal->occurred_at);return same.ok&&same.value==0;
}
Outcome<Integer> actual_wage_periods(const PrivateShopContext&x,const PrivateShopOperation&o){
 if(!exact_operation(x,o))return {true,Integer(o.attendance_ticks.size()),{}};
 if(&x.exact_operations->shops!=&x||!o.attendance_ticks.empty())return {false,0,common_failure("PrivateShopExactWageOwnerMismatch",o.id).error};
 Integer count=0;for(const auto&row:x.exact_operations->sources.labor_applied_sources)if(row.operation_ref==o.id){auto read=read_original_private_shop_labor_for_wage(*x.exact_operations,{private_shop_labor_applied_source(row.id),1});if(!read.ok)return {false,0,read.error};++count;}
 if(count<0||count>2)return {false,0,common_failure("PrivateShopExactLaborCountMismatch",o.id).error};return {true,count,{}};
}
Status actual_wage_period(const PrivateShopContext&x,const PrivateShopOperation&o,const PrivateShopStaffService&service){
 if(!exact_operation(x,o))return service.tick==o.attendance_ticks[std::size_t(service.attendance_index-1)]?common_success():common_failure("PrivateShopStaffAttendanceMismatch",service.id);
 const PrivateShopLaborAppliedSource*found=nullptr;for(const auto&row:x.exact_operations->sources.labor_applied_sources)if(row.operation_ref==o.id&&row.work_period_ref.period_ordinal==service.attendance_index-1){if(found)return common_failure("PrivateShopDuplicateLaborPeriod",o.id);found=&row;}
 if(!found||!found->original_staff_service_ref||!same_source_ref(*found->original_staff_service_ref,{private_shop_module,"private_shop_staff_served",service.id})||found->occurred_at.half_day_tick!=service.tick)return common_failure("PrivateShopStaffExactLaborMismatch",service.id);
 auto read=read_original_private_shop_labor_for_wage(*x.exact_operations,{private_shop_labor_applied_source(found->id),1});return read.ok?common_success():Status{false,{},read.error};
}
// 两腿和预约同recipe；不先扣钱再另写可消费的影子工资余额。
Status pay(CommonStore& c,LocalEconomyState& economy,PrivateShopState& state,const PrivateShopOperation& operation,Integer tick,bool closing,Integer attendance_index,SourceRef* original_service=nullptr){const auto* contract=state.staff.contracts.find(operation.staff_contract_id);if(!contract)return common_failure("PrivateShopStaffContractMissing");const auto terms=contract->terms;const auto obligation=contract->obligation_id;const auto* old_remainder=economy.obligation_remainders.find(obligation);if(!old_remainder)return common_failure("PrivateShopStaffRemainderMissing");const Integer remainder=*old_remainder;Integer amount=closing?1:(3+remainder)/2,next=closing?0:(3+remainder)%2;if((closing&&remainder!=1)||remainder<0||remainder>1)return common_failure("PrivateShopStaffRemainderMismatch");auto held=reserved(c,terms.payer_wallet_id,operation.id);if(!held.ok)return {false,{},held.error};if(held.value<amount)return common_failure("PrivateShopStaffReservationShortfall");const auto* payer=c.wallet(terms.payer_wallet_id);const auto* payee=c.wallet(terms.payee_wallet_id);if(!payer||!payee||!owner_equal(payer->owner,{Owner::Kind::actor,terms.employer_actor_id,{}})||!owner_equal(payee->owner,{Owner::Kind::actor,terms.worker_actor_id,{}}))return common_failure("PrivateShopStaffPaymentOwnerMismatch");auto service=fact(c,"private_shop_staff_service","private_shop_staff_served",private_shop_module);if(!service.ok)return {false,{},service.error};auto due=fact(c,"local_due","wage_due","local_economy");if(!due.ok)return {false,{},due.error};if(!economy.arrears.insert(due.value,{due.value,obligation,tick,amount,0}))return common_failure("PrivateShopStaffDuplicateDue");const Integer left=held.value-amount;ResourceRecipe recipe;recipe.operations.push_back(SetReservation{terms.payer_wallet_id,{ReservationRef::Kind::action,operation.id},left,left==0});auto changed=resource_recipe::append_money_transfer(recipe,terms.payer_wallet_id,terms.payee_wallet_id,amount,resource_recipe::MoneyTransferPolicy::spendable_debit_original_credit);if(!changed.ok)return changed;changed=c.apply_resources(recipe);if(!changed.ok)return changed;auto payment=fact(c,"local_payment","obligation_payment","local_economy");if(!payment.ok)return {false,{},payment.error};if(!economy.payments.insert(payment.value,{payment.value,due.value,obligation,terms.payer_wallet_id,terms.payee_wallet_id,tick,tick,amount,contract->id}))return common_failure("PrivateShopStaffDuplicatePayment");economy.arrears.find(due.value)->paid_amount=amount;*economy.obligation_remainders.find(obligation)=next;economy.obligations.find(obligation)->last_receipt_id=payment.value;if(!state.staff.services.insert(service.value,{service.value,contract->id,operation.id,due.value,payment.value,tick,attendance_index,amount,remainder,next,closing}))return common_failure("PrivateShopStaffDuplicateService");if(original_service)*original_service={private_shop_module,"private_shop_staff_served",service.value};return common_success();}
}
Outcome<StableId> private_shop_operation_staff(const PrivateShopContext& x,const PrivateShopRecord& shop,const StableId& actor){if(actor==shop.terms.proprietor_actor_id)return {true,{}, {}};const PrivateShopStaffContract* selected=nullptr;for(const auto& row:x.state.staff.contracts.rows())if(row.second.status=="active"&&row.second.terms.shop_id==shop.id&&row.second.terms.worker_actor_id==actor){if(selected)return fail<StableId>("PrivateShopStaffAlreadyAssigned");selected=&row.second;}if(!selected)return fail<StableId>("PrivateShopOperatorRequired");if(x.common.tick()>INT64_MAX-2||selected->accepted_tick>x.common.tick()||selected->through_tick<x.common.tick()+2)return fail<StableId>("PrivateShopStaffTermTooShort");if(!x.estates||!x.estate_access)return fail<StableId>("PrivateShopLaborSourceUnavailable");if(x.estate_access->army_id&&!x.estate_access->army_id(actor).empty())return fail<StableId>("PrivateShopWorkerInArmy");if(!x.estate_employment)for(const auto& fact:x.common.state().facts.rows())if(fact.second.domain==estate_employment_module)return fail<StableId>("PrivateShopEmploymentHistoryUnavailable");if(x.estate_employment)for(const auto& row:x.estate_employment->contracts.rows())if(row.second.status=="active"&&row.second.terms.worker_actor_id==actor)return fail<StableId>("PrivateShopWorkerAlreadyEmployed");for(const auto& row:x.estates->estates.rows()){const auto* duty=row.second.duties.find(actor);if(row.second.manager_actor_id==actor||(duty&&*duty!="idle"))return fail<StableId>("PrivateShopWorkerEstateDuty");}return {true,selected->id,{}};}
Status reserve_private_shop_staff_day(CommonStore& c,const PrivateShopContext& x,const PrivateShopOperation& operation){if(operation.staff_contract_id.empty())return common_success();const auto* contract=x.state.staff.contracts.find(operation.staff_contract_id);if(!contract||contract->status!="active"||contract->terms.worker_actor_id!=operation.actor_id||contract->terms.shop_id!=operation.shop_id)return common_failure("PrivateShopStaffContractMismatch");auto held=reserved(c,contract->terms.payer_wallet_id,operation.id);if(!held.ok)return {false,{},held.error};if(held.value)return common_failure("PrivateShopStaffDuplicateReservation");return c.apply_resources({{SetReservation{contract->terms.payer_wallet_id,{ReservationRef::Kind::action,operation.id},3,false}},{}});}
Status record_private_shop_staff_attendance(CommonStore& c,LocalEconomyState& economy,PrivateShopState& state,const PrivateShopContext& x,const StableId& id,Integer tick){if(&c!=&x.common||&economy!=&x.economy||&state!=&x.state||!x.phase||x.phase->from_tick!=c.tick()||c.tick()==INT64_MAX||x.phase->to_tick!=c.tick()+1||tick!=x.phase->to_tick)return common_failure("PrivateShopStaffPhaseMismatch");const auto* operation=state.operations.find(id);if(!operation||operation->attendance_ticks.empty()||operation->attendance_ticks.back()!=tick||!c.action(id)||!operation->result_fact_id.empty())return common_failure("PrivateShopStaffAttendanceRequired");if(operation->staff_contract_id.empty())return common_success();for(const auto& row:state.staff.services.rows())if(row.second.operation_id==id&&!row.second.closing_fraction&&row.second.attendance_index==Integer(operation->attendance_ticks.size()))return common_failure("PrivateShopDuplicateAttendanceWage",id);return pay(c,economy,state,*operation,tick,false,Integer(operation->attendance_ticks.size()));}
Outcome<std::optional<SourceRef>> record_private_shop_staff_exact_labor(CommonStore&c,LocalEconomyState&economy,PrivateShopState&state,const PrivateShopOperationSourceContext&x,const SourceRef&source){
 if(&c!=&x.shops.common||&economy!=&x.shops.economy||&state!=&x.shops.state)return {false,{},common_failure("PrivateShopExactWageCandidateMismatch",source.id).error};
 auto labor=read_original_private_shop_labor_for_wage(x,{source,1});if(!labor.ok)return {false,{},labor.error};
 const auto&row=*labor.value;auto at=x.clock.read_current_moment();if(!at.ok)return {false,{},at.error};auto same=compare_world_moments(at.value,row.occurred_at);if(!same.ok)return {false,{},same.error};
 const auto*operation=state.operations.find(row.operation_ref);const auto*action=operation?c.action(operation->id):nullptr;
 if(same.value||!operation||!action||!operation->result_fact_id.empty()||!operation->attendance_ticks.empty()||row.original_staff_service_ref)return {false,{},common_failure("PrivateShopFreshExactLaborRequired",source.id).error};
 if(operation->staff_contract_id.empty())return {true,std::nullopt,{}};
 const Integer index=row.work_period_ref.period_ordinal+1;
 for(const auto&old:state.staff.services.rows())if(old.second.operation_id==operation->id&&!old.second.closing_fraction&&old.second.attendance_index==index)return {false,{},common_failure("PrivateShopDuplicateAttendanceWage",source.id).error};
 SourceRef original;auto paid=pay(c,economy,state,*operation,row.occurred_at.half_day_tick,false,index,&original);if(!paid.ok)return {false,{},paid.error};return {true,original,{}};
}
Outcome<Integer> finish_private_shop_staff_day(CommonStore& c,LocalEconomyState& economy,PrivateShopState& state,const PrivateShopContext& x,const StableId& id,Integer tick){if(&c!=&x.common||&economy!=&x.economy||&state!=&x.state)return fail<Integer>("PrivateShopCandidateMismatch");const auto* operation=state.operations.find(id);if(!operation||!c.action(id)||!operation->result_fact_id.empty())return fail<Integer>("PrivateShopStaffAttendanceRequired");if(operation->staff_contract_id.empty())return {true,0,{}};const auto* contract=state.staff.contracts.find(operation->staff_contract_id);if(!contract)return fail<Integer>("PrivateShopStaffContractMissing");auto actual_periods=actual_wage_periods(x,*operation);if(!actual_periods.ok)return {false,{},actual_periods.error};const auto* remainder=economy.obligation_remainders.find(contract->obligation_id);if(!remainder)return fail<Integer>("PrivateShopStaffRemainderMissing");if(*remainder){auto valid=pay(c,economy,state,*operation,tick,true,actual_periods.value);if(!valid.ok)return {false,{},valid.error};}auto changed=c.apply_resources({{SetReservation{contract->terms.payer_wallet_id,{ReservationRef::Kind::action,id},0,true}},{}});if(!changed.ok)return {false,{},changed.error};Integer total=0;for(const auto& row:state.staff.services.rows())if(row.second.operation_id==id&&__builtin_add_overflow(total,row.second.amount,&total))return fail<Integer>("PrivateShopStaffWageOverflow");return {true,total,{}};}
// 完整服务回放以原Action的到岗次数为唯一劳动量，再逐原LE应付/支付及事实序证明款项。
Status validate_private_shop_staff_services(const PrivateShopContext& x){std::set<StableId> used,dues,payments;std::map<StableId,Integer> remainders;std::map<StableId,StableId> last_payments;
 for(const auto& actual:x.common.state().facts.rows()){const auto* service=x.state.staff.services.find(actual.first);if(!service)continue;const auto& s=*service;const auto* o=x.state.operations.find(s.operation_id);const auto* contract=x.state.staff.contracts.find(s.contract_id);const auto* due=x.economy.arrears.find(s.arrear_id);const auto* paid=x.economy.payments.find(s.payment_id);auto actual_periods=o?actual_wage_periods(x,*o):Outcome<Integer>{false,0,common_failure("PrivateShopOperationMissing",s.id).error};if(!actual_periods.ok)return {false,{},actual_periods.error};const Integer prior=remainders[s.contract_id];const Integer expected=s.closing_fraction?1:(3+prior)/2,next=s.closing_fraction?0:(3+prior)%2;const auto serial=organization_instance_sequence(s.id,"private_shop_staff_service"),d=organization_instance_sequence(s.arrear_id,"local_due"),p=organization_instance_sequence(s.payment_id,"local_payment");
  if(s.id!=actual.first||!o||!contract||o->staff_contract_id!=contract->id||o->actor_id!=contract->terms.worker_actor_id||o->shop_id!=contract->terms.shop_id||o->item_id!=contract->terms.service_item_id||!serial||!d||!p||*d!=*serial+1||*p!=*d+1||!head(x.common,s.id,"private_shop_staff_service","private_shop_staff_served",private_shop_module)||!before(x.common,o->id,s.id)||!used.insert(s.id).second||!dues.insert(s.arrear_id).second||!payments.insert(s.payment_id).second||s.remainder_before!=prior||s.remainder_after!=next||s.amount!=expected||s.attendance_index<1||s.attendance_index>actual_periods.value||s.tick>contract->through_tick||(!contract->terminal_fact_id.empty()&&!before(x.common,s.payment_id,contract->terminal_fact_id)))return common_failure("InvalidPrivateShopStaffService",s.id);
  if(s.closing_fraction){const auto* result=x.state.operating_results.find(o->result_fact_id);if(prior!=1||!result||result->completed||s.attendance_index!=1||actual_periods.value!=1||s.tick!=result->tick||!before(x.common,s.payment_id,result->id))return common_failure("PrivateShopStaffFractionSourceMismatch",s.id);}else{auto actual=actual_wage_period(x,*o,s);if(!actual.ok)return actual;}
  if(!due||!paid||!head(x.common,due->id,"local_due","wage_due","local_economy")||!head(x.common,paid->id,"local_payment","obligation_payment","local_economy")||!before(x.common,s.id,due->id)||!before(x.common,due->id,paid->id)||due->obligation_id!=contract->obligation_id||due->due_tick!=s.tick||due->original_due!=s.amount||due->paid_amount!=s.amount||paid->arrear_id!=due->id||paid->obligation_id!=contract->obligation_id||paid->from_wallet_id!=contract->terms.payer_wallet_id||paid->to_wallet_id!=contract->terms.payee_wallet_id||paid->tick!=s.tick||paid->due_tick!=s.tick||paid->amount!=s.amount||paid->authority_ref!=contract->id)return common_failure("PrivateShopStaffWageReceiptMismatch",s.id);remainders[s.contract_id]=next;last_payments[s.contract_id]=s.payment_id;
 }
 if(used.size()!=x.state.staff.services.size())return common_failure("PrivateShopStaffServiceRegistryMismatch");
 for(const auto& row:x.state.operations.rows()){const auto& o=row.second;auto actual_periods=actual_wage_periods(x,o);if(!actual_periods.ok)return {false,{},actual_periods.error};if(o.staff_contract_id.empty()){for(const auto& s:x.state.staff.services.rows())if(s.second.operation_id==o.id)return common_failure("PrivateShopUnexpectedStaffService",o.id);continue;}const auto* contract=x.state.staff.contracts.find(o.staff_contract_id);if(!contract||!before(x.common,contract->id,o.id)||o.start_tick<contract->accepted_tick||o.start_tick>INT64_MAX-2||o.start_tick+2>contract->through_tick||!original_staff_terminal_order(x,o,*contract))return common_failure("PrivateShopStaffOperationMismatch",o.id);std::set<Integer> indices;Integer cash=0;bool closing=false;for(const auto& s:x.state.staff.services.rows())if(s.second.operation_id==o.id){if(s.second.closing_fraction){if(closing)return common_failure("PrivateShopDuplicateClosingWage",o.id);closing=true;}else if(!indices.insert(s.second.attendance_index).second)return common_failure("PrivateShopDuplicateAttendanceWage",o.id);if(__builtin_add_overflow(cash,s.second.amount,&cash))return common_failure("PrivateShopStaffWageOverflow");}if(Integer(indices.size())!=actual_periods.value)return common_failure("PrivateShopMissingAttendanceWage",o.id);for(const auto& wallet:x.common.state().wallets.rows())for(const auto& hold:wallet.second.reserved)if(hold.action_id.kind==ReservationRef::Kind::action&&hold.action_id.id==o.id&&wallet.first!=contract->terms.payer_wallet_id)return common_failure("PrivateShopForeignStaffReservation",o.id);for(const auto& inventory:x.common.state().inventories.rows())for(const auto& lot:inventory.second.lots)if(lot.reserved_by.kind==ReservationRef::Kind::action&&lot.reserved_by.id==o.id)return common_failure("PrivateShopUnexpectedStaffStockReservation",o.id);auto held=reserved(x.common,contract->terms.payer_wallet_id,o.id);if(!held.ok)return {false,{},held.error};if(o.result_fact_id.empty()){if(closing||cash>3||held.value!=3-cash||contract->status!="active")return common_failure("PrivateShopStaffReservationMismatch",o.id);}else{const auto* result=x.state.operating_results.find(o.result_fact_id);const Integer expected=(actual_periods.value*3+1)/2;if(!result||cash!=expected||result->wage_paid!=cash||held.value||closing!=(actual_periods.value==1))return common_failure("PrivateShopStaffClosedDayMismatch",o.id);}}
 for(const auto& row:x.state.staff.contracts.rows()){const auto& contract=row.second;const auto* remainder=x.economy.obligation_remainders.find(contract.obligation_id);const auto* obligation=x.economy.obligations.find(contract.obligation_id);if(!remainder||!obligation||*remainder!=remainders[row.first]||obligation->last_receipt_id!=last_payments[row.first])return common_failure("PrivateShopStaffWageHistoryMismatch",row.first);for(const auto& due:x.economy.arrears.rows())if(due.second.obligation_id==contract.obligation_id&&!dues.count(due.first))return common_failure("PrivateShopUnprovenStaffDue",due.first);for(const auto& paid:x.economy.payments.rows())if(paid.second.obligation_id==contract.obligation_id&&!payments.count(paid.first))return common_failure("PrivateShopUnprovenStaffPayment",paid.first);}
 return common_success();}
}
